def transform(grid):
    h, w = len(grid), len(grid[0])
    zeros = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 0]
    r0 = min(r for r, c in zeros)
    r1 = max(r for r, c in zeros)
    c0 = min(c for r, c in zeros)
    c1 = max(c for r, c in zeros)
    height, width = r1 - r0 + 1, c1 - c0 + 1

    seeds = {}
    for r in range(r0, r1 + 1):
        for c in range(c0, c1 + 1):
            color = grid[r][c]
            if color != 0:
                seeds.setdefault(color, (r - r0, c - c0))

    result = [[0] * width for _ in range(height)]

    for color, (sr, sc) in seeds.items():
        seen = set()
        count = 0

        for r in range(h):
            for c in range(w):
                if r0 <= r <= r1 and c0 <= c <= c1:
                    continue
                if grid[r][c] != color or (r, c) in seen:
                    continue

                count += 1
                stack = [(r, c)]
                seen.add((r, c))
                while stack:
                    cr, cc = stack.pop()
                    for dr in (-1, 0, 1):
                        for dc in (-1, 0, 1):
                            nr, nc = cr + dr, cc + dc
                            if not (0 <= nr < h and 0 <= nc < w):
                                continue
                            if r0 <= nr <= r1 and c0 <= nc <= c1:
                                continue
                            if grid[nr][nc] == color and (nr, nc) not in seen:
                                seen.add((nr, nc))
                                stack.append((nr, nc))

        for k in range(count):
            c = sc + 2 * k
            if c < width:
                result[sr][c] = color

    return result
